        for (int w = 0; w < 8; w++) { float2 p = pst[w*T + t]; s1 += p.x; s2 += p.y; }
        const float mu = s1 * (1.f/C); const float rs = rsqrtf(fmaxf(s2*(1.f/C) - mu*mu, 0.f) + 1e-6f);
        if (rs == 12345.f) sink[0] = mu + (float)dbuf[t];
      }
      asm volatile("bar.sync 1, 256;" ::: "memory");
    }
  }
  __syncthreads();
  if (tid == 0) { stamps[blockIdx.x*2] = gtime() - t0; stamps[blockIdx.x*2+1] = (u64)(clock64() - c0); }
}
__global__ void __launch_bounds__(288,1) k64(const float* x, const float* dwp, const float* dwb, int B, int mode, u64* st, float* sink)
{ body<96,112,112,2,7,16,2,1>(x,dwp,dwb,B,mode,st,sink); }
__global__ void __launch_bounds__(288,1) k32r4(const float* x, const float* dwp, const float* dwb, int B, int mode, u64* st, float* sink)
{ body<128,64,64,4,4,16,3,1>(x,dwp,dwb,B,mode,st,sink); }
__global__ void __launch_bounds__(288,1) k32r2(const float* x, const float* dwp, const float* dwb, int B, int mode, u64* st, float* sink)
{ body<128,64,64,2,4,16,3,2>(x,dwp,dwb,B,mode,st,sink); }

extern "C" const char* gate_launch(int which, const float* x, const float* dwp, const float* dwb, int B, int mode, void* st, float* sink, void* stream) {
  cudaStream_t s = (cudaStream_t)stream;
  if (which == 0) { cudaFuncSetAttribute(k64, cudaFuncAttributeMaxDynamicSharedMemorySize, 200000); k64<<<148, 288, 193000, s>>>(x, dwp, dwb, B, mode, (u64*)st, sink); }
  else if (which == 1) { cudaFuncSetAttribute(k32r4, cudaFuncAttributeMaxDynamicSharedMemorySize, 227000); k32r4<<<148, 288, 220000, s>>>(x, dwp, dwb, B, mode, (u64*)st, sink); }
  else { cudaFuncSetAttribute(k32r2, cudaFuncAttributeMaxDynamicSharedMemorySize, 227000); k32r2<<<148, 288, 200000, s>>>(x, dwp, dwb, B, mode, (u64*)st, sink); }
  cudaError_t e = cudaGetLastError();
  return e == cudaSuccess ? nullptr : cudaGetErrorString(e);
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
extern "C" const char* gate_launch(int which, const float* x, const float* dwp, const float* dwb, int B, int mode, void* st, float* sink, void* stream);
void run(torch::Tensor x, torch::Tensor dwp, torch::Tensor dwb, torch::Tensor st, torch::Tensor sink) {
