    return torch.tensor([int(v) for v in tm.opaque], dtype=torch.int64).view(torch.uint8).cuda()
cfgs = {'k64':((96,112,112,2,7,16,2,1,8),64,288), 'k64c':((96,112,112,2,7,16,2,1,8),64,512),
        'k32':((128,64,64,4,4,16,3,1,10),32,288), 'k32c':((128,64,64,4,4,16,3,1,10),32,512)}
for name,(cf,B,NTH) in cfgs.items():
    C,H,W,R,PW,CG,NS,DBUF,NROW = cf
    SF = CG*NROW*(W+8); T=R*W; DB=((T+63)//64)*C*128; SPI=(H+R-1)//R
    sm = ((NS*SF*4+1023)//1024)*1024 + DBUF*DB + 8*T*8 + 64
    k = cuda_kernel(BODY, name); k.set_smem(sm)
    torch.manual_seed(0)
    x = torch.randn(B,C,H,W, device='cuda')
    mp = mkmap(x, B, C, H, W, (W+8, NROW, CG))
    dw = torch.randn(C,7,7, device='cuda')*0.38
    dwp = torch.zeros(C,7,8, device='cuda'); dwp[:,:,:7] = dw
    dwb = torch.randn(C, device='cuda')
    st = torch.zeros(148*2, dtype=torch.int64, device='cuda'); sink = torch.zeros(4, device='cuda')
    dbg = torch.zeros(2*(DB+T*8), dtype=torch.uint8, device='cuda')
    if NTH == 288:
        k((148,), (NTH,), mp, dwp, dwb, B, 0, st, sink, dbg, smem=sm); torch.cuda.synchronize()
        d = torch.nn.functional.conv2d(x, dw.view(C,1,7,7), dwb, padding=3, groups=C)
        ntiles = B*SPI
        for which, (blk, tile) in enumerate([(0, 0), (147, ntiles*148//148 - 1)]):
            raw = dbg[which*(DB+T*8):(which*(DB+T*8)+DB)].view(torch.float16).float()
            bb, h0 = tile // SPI, (tile % SPI)*R
            t = torch.arange(T, device='cuda'); c = torch.arange(C, device='cuda')
            tt, cc = t.view(1,-1), c.view(-1,1)
            byte = (tt>>6)*(C*128) + cc*128 + ((((tt&63)>>3) ^ (cc&7))<<4) + (tt&7)*2
            got = raw[(byte//2)]
            ref = d[bb, :, h0:h0+R, :].reshape(C, T)
            ref16 = ref.half().float()
            stats = dbg[which*(DB+T*8)+DB:(which+1)*(DB+T*8)].view(torch.float32).view(T,2)
            mu = ref16.mean(0); rs = 1/torch.sqrt(ref16.var(0, unbiased=False)+1e-6)
            print(name, 'tile', tile, 'h0', h0, 'd maxerr vs fp16(ref)', (got-ref16).abs().max().item(), 'vs ref', (got-ref).abs().max().item(),
                  'mu err', (stats[:,0]-mu).abs().max().item(), 'rs rel err', ((stats[:,1]-rs)/rs).abs().max().item())
    nul = torch.zeros(1, dtype=torch.uint8, device='cuda')
    for mode in (0,1):
        fn = lambda x_, dwp_, dwb_, st_, sink_: k((148,), (NTH,), mp, dwp_, dwb_, B, mode, st_, sink_, 0, smem=sm) if False else k((148,), (NTH,), mp, dwp_, dwb_, B, mode, st_, sink_, b200probe.i64(0), smem=sm)
        us = harness_time(fn, [x, dwp, dwb], [st, sink])
        print(f"{name} threads {NTH} mode{mode}: harness {us:.1f} us")

