        for (int g = 0; g < NG; g++, it++) {
          const int s = it % NS; const u32 ph = (it / NS) & 1;
          mb_wait(empty+s, ph^1);
          if (mode == 1) { mb_arrive(full+s); continue; }
          mb_expect(full+s, (u32)(SF*4));
          tma3(ring + s*SF, map, -4, h0-3, b*C + g*CG, full+s);
        }
      }
    }
  } else if (warp < 8) {
    const int cl = tid / PPC, j = tid - cl*PPC, w0 = j*PW;
    int it = 0;
    for (int tile = tb; tile < te; tile++) {
      float ssum[R*PW], ssq[R*PW];
#pragma unroll
      for (int k = 0; k < R*PW; k++) { ssum[k] = 0.f; ssq[k] = 0.f; }
      unsigned char* dbuf = dt + (DBUF == 2 ? (tile & 1)*DB : 0);
#pragma unroll 1
      for (int g = 0; g < NG; g++, it++) {
        const int s = it % NS; const u32 ph = (it / NS) & 1;
        const int c = g*CG + cl;
        float wt[49];
        const float4* wp4 = reinterpret_cast<const float4*>(dwp + c*56);
#pragma unroll
        for (int r = 0; r < 7; r++) { float4 a = __ldg(wp4 + 2*r), bq = __ldg(wp4 + 2*r + 1);
          wt[r*7+0]=a.x; wt[r*7+1]=a.y; wt[r*7+2]=a.z; wt[r*7+3]=a.w; wt[r*7+4]=bq.x; wt[r*7+5]=bq.y; wt[r*7+6]=bq.z; }
        const float bias = __ldg(dwb + c);
        mb_wait(full+s, ph);
        float acc[R][PW];
#pragma unroll
        for (int r = 0; r < R; r++)
#pragma unroll
          for (int cc = 0; cc < PW; cc++) acc[r][cc] = 0.f;
        if (mode != 2) {
          const float* xb = ring + s*SF + cl*CS + w0 + 1;
#pragma unroll
          for (int i = 0; i < R+6; i++) {
            float v[PW+6];
            const float* rp = xb + i*RS;
            if (PW % 4 == 0) {
              float tmp[PW+8];
              const float4* q4 = reinterpret_cast<const float4*>(rp - 1);
#pragma unroll
              for (int k = 0; k < (PW+8)/4; k++) { float4 a = q4[k]; tmp[4*k]=a.x; tmp[4*k+1]=a.y; tmp[4*k+2]=a.z; tmp[4*k+3]=a.w; }
#pragma unroll
              for (int m = 0; m < PW+6; m++) v[m] = tmp[m+1];
            } else {
#pragma unroll
              for (int m = 0; m < PW+6; m++) v[m] = rp[m];
            }
#pragma unroll
            for (int r = 0; r < R; r++) {
              const int ki = i - r;
              if (ki >= 0 && ki < 7) {
#pragma unroll
                for (int cc = 0; cc < PW; cc++)
#pragma unroll
                  for (int jj = 0; jj < 7; jj++) acc[r][cc] = fmaf(v[cc+jj], wt[ki*7+jj], acc[r][cc]);
              }
            }
          }
        }
        __syncwarp();
        if (lane == 0) mb_arrive(empty+s);
#pragma unroll
        for (int r = 0; r < R; r++)
#pragma unroll
          for (int cc = 0; cc < PW; cc++) {
            const int t = r*W + w0 + cc;
            const u16 hv = f2h(acc[r][cc] + bias);
            const float df = h2f(hv);
            ssum[r*PW+cc] += df; ssq[r*PW+cc] = fmaf(df, df, ssq[r*PW+cc]);
            const int byte = (t>>6)*(C*128) + c*128 + ((((t&63)>>3) ^ (c&7))<<4) + (t&7)*2;
            *reinterpret_cast<u16*>(dbuf + byte) = hv;
          }
      }
#pragma unroll
      for (int k = 0; k < R*PW; k++) { ssum[k] += __shfl_xor_sync(0xffffffffu, ssum[k], 16); ssq[k] += __shfl_xor_sync(0xffffffffu, ssq[k], 16); }
      if (lane < 16) {
#pragma unroll
        for (int r = 0; r < R; r++)
#pragma unroll
          for (int cc = 0; cc < PW; cc++) pst[warp*T + r*W + w0 + cc] = make_float2(ssum[r*PW+cc], ssq[r*PW+cc]);
      }
      asm volatile("bar.sync 1, 256;" ::: "memory");
      for (int t = tid; t < T; t += 256) {   // per-token LN statistics of the fp16-rounded d (STEP 2: hand to epilogue)
        float s1 = 0.f, s2 = 0.f;
#pragma unroll
        for (int w = 0; w < 8; w++) { float2 p = pst[w*T + t]; s1 += p.x; s2 += p.y; }
        const float mu = s1 * (1.f/C); const float rs = rsqrtf(fmaxf(s2*(1.f/C) - mu*mu, 0.f) + 1e-6f);
        if (rs == 12345.f) sink[0] = mu + (float)dbuf[t];
      }
      asm volatile("bar.sync 1, 256;" ::: "memory");
    }
  }
  __syncthreads();
}
